mapper.select:
SELECT asub.*,
       u.name AS studentName,
       a.title AS assignmentTitle
FROM assignment_submissions asub
LEFT JOIN users u ON asub.student_id = u.id
LEFT JOIN assignments a ON asub.assignment_id = a.id
WHERE 1=1
AND asub.assignment_id = #{assignmentId}
AND asub.student_id = #{studentId}
AND asub.graded = #{graded}
ORDER BY ${sortBy} ${order}
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM assignment_submissions
WHERE 1=1
AND assignment_id = #{assignmentId}
AND student_id = #{studentId}
AND graded = #{graded}

SELECT DATE_FORMAT(asub.submission_date, '%Y-%m-%d') AS day, AVG(asub.score) AS avgScore
FROM assignment_submissions asub
JOIN assignments a ON asub.assignment_id = a.id
JOIN class_students cs ON cs.student_id = asub.student_id 
WHERE a.teacher_id = #{teacherId}
AND asub.score IS NOT NULL AND CAST(asub.graded AS UNSIGNED) = 1
AND asub.submission_date >= #{startDate}
AND asub.submission_date <= #{endDate}
AND a.course_id = #{courseId}
AND cs.class_id = #{classId}
GROUP BY DATE_FORMAT(asub.submission_date, '%Y-%m-%d')
ORDER BY day
